import type { TextBlockParam } from '@anthropic-ai/sdk/resources/index.mjs'
import * as React from 'react'
import { BLACK_CIRCLE } from '../../constants/figures.js'
import { Box, Text, type TextProps } from '../../ink.js'
import type { MessageOrigin } from '../../types/message.js'
import { parseTaskNotificationDetails } from '../../utils/taskNotification.js'

type Props = {
  addMargin: boolean
  param: TextBlockParam
  origin?: MessageOrigin
}

function getStatusColor(status: string | undefined): TextProps['color'] {
  switch (status) {
    case 'completed':
      return 'success'
    case 'failed':
      return 'error'
    case 'killed':
      return 'warning'
    default:
      return 'text'
  }
}

export function UserAgentNotificationMessage({
  addMargin,
  param: { text },
  origin,
}: Props): React.ReactNode {
  const details =
    origin?.kind === 'task-notification'
      ? origin
      : parseTaskNotificationDetails(text)

  if (!details?.summary) {
    return null
  }

  const color = getStatusColor(details.status)

  return (
    <Box marginTop={addMargin ? 1 : 0}>
      <Text>
        <Text color={color}>{BLACK_CIRCLE}</Text> {details.summary}
      </Text>
    </Box>
  )
}
